INSERT INTO "recommendations" ("tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at")
VALUES (NULL, NULL, 499, 'God of War III', 'God of War III', 'game', 2010, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3koi.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sdokfipunkjyry01pcv9.jpg', 'Set in the realm of brutal Greek mythology, God of War III is a single-player game that allows players to take on the climatic role of the ex-Spartan warrior, Kratos, as he scales through the intimidating heights of Mt. Olympus and the dark depths of Hell to seek revenge on those who have betrayed him. Armed with double-chained blades, and an array of new weapons and magic for this iteration of the trilogy, Kratos must take on mythology''s darkest creatures while solving intricate puzzles throughout his merciless quest to destroy Olympus. Utilizing a new game engine built from the ground up and state-of-the-art visual technologies, the development team behind God of War III has made standard-setting strides in giving players the realistic feel of actually being on the battlegrounds. With texture resolutions quadrupling since God of War II on PlayStation 2 computer entertainment system, God of War III, in its debut on the PS3 system, will feature fluid, life-like characters, as well as dynamic lighting effects, a robust weapon system, and world-changing scenarios that will truly bring unmistakable realism to Kratos'' fateful quest. Players will have a chance to join battles on a grand scale that is four times larger than its predecessor.', 'https://www.igdb.com/games/god-of-war-iii', '["PlayStation 3"]', NULL, 9.1, 0, 1.12, '2026-11-22 03:06:26', '2026-11-22 03:06:26')
