VALUES (NULL, NULL, 282831, 'The Blood of Dawnwalker', 'The Blood of Dawnwalker', 'game', 2026, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cob7ym.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar6fae.jpg', 'The Blood of Dawnwalker is an open-world dark fantasy action RPG set in 14th-century Europe. You play as Coen, human by day and vampire by night, fighting to save your family in a story shaped by your actions and the secrets you uncover.', 'https://www.igdb.com/games/the-blood-of-dawnwalker', '["Xbox Series X|S", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, 8.2, 0, 1.12, '2026-11-22 03:06:26', '2026-11-22 03:06:26')
