VALUES (NULL, NULL, 1011, 'Borderlands 2', 'Borderlands 2', 'game', 2012, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9ba3.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3m0y.jpg', 'A new era of shoot and loot is about to begin. Play as one of four new vault hunters facing off against a massive new world of creatures, psychos and the evil mastermind, Handsome Jack. Make new friends, arm them with a bazillion weapons and fight alongside them in 4 player co-op on a relentless quest for revenge and redemption across the undiscovered and unpredictable living planet.', 'https://www.igdb.com/games/borderlands-2', '["PlayStation 3", "PlayStation 4", "Linux", "Android", "PC (Microsoft Windows)", "Mac", "PlayStation Vita", "Xbox 360", "Xbox One", "Nintendo Switch"]', NULL, 8.2, 0, 1.06, '2026-11-22 03:06:26', '2026-11-22 03:06:26')
