VALUES (NULL, NULL, 2273, 'No More Heroes 2: Desperate Struggle', 'No More Heroes 2: Desperate Struggle', 'game', 2010, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cobp4c.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arcau.jpg', 'No More Heroes 2: Desperate Struggle continues the tale of punk anti-hero Travis Touchdown, the Japanese anime Otaku, and pro wrestling-obsessed assassin. Travis finds himself at the bottom of the UAA (United Assassins Association) rankings and must wage war to become the No. 1 assassin once again. The follow-up to the popular No More Heroes will offer fans infectious, fun gameplay that allows you to wield not just one, but two swords and face multiple bosses simultaneously in bigger-than-ever boss battles.', 'https://www.igdb.com/games/no-more-heroes-2-desperate-struggle', '["Wii", "PC (Microsoft Windows)", "Nintendo Switch"]', NULL, 7.9, 0, 1.02, '2026-11-22 03:06:26', '2026-11-22 03:06:26')
