VALUES (NULL, NULL, 102584, 'Dying Light 2: Stay Human', 'Dying Light 2: Stay Human', 'game', 2022, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co65yk.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar5vy.jpg', 'The last great human settlement exists within an unforgiving, infected world. Exceptional agility and combat skills make you a powerful ally and a valuable commodity. With your unique abilities you have the power to be an agent of change within this decaying metropolis. Use it wisely.', 'https://www.igdb.com/games/dying-light-2-stay-human', '["Xbox Series X|S", "PlayStation 4", "PC (Microsoft Windows)", "PlayStation 5", "Xbox One"]', NULL, 7.4, 0, 1.03, '2026-11-22 03:06:26', '2026-11-22 03:06:26')
