VALUES (NULL, NULL, 314252, 'Dying Light: The Beast', 'Dying Light: The Beast', 'game', 2025, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cocmja.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar495d.jpg', 'Dying Light: The Beast Restored Land is a new enhanced version of the game that includes the base game, all previously released updates and the premiere Restored Land content in one package. This includes Legend Levels, New Game+, Ray Tracing, Nightmare Mode, dozens of new brutal finishers, hundreds of parkour and gameplay improvements, and numerous visual and audio enhancements - delivering new ways to experience the apocalypse.', 'https://www.igdb.com/games/dying-light-the-beast', '["Xbox Series X|S", "PlayStation 4", "PC (Microsoft Windows)", "PlayStation 5", "Xbox One"]', NULL, 7.6, 0, 1.03, '2026-11-22 03:06:26', '2026-11-22 03:06:26')
