VALUES (NULL, NULL, 118, 'Star Wars: Knights of the Old Republic II - The Sith Lords', 'Star Wars: Knights of the Old Republic II - The Sith Lords', 'game', 2004, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1qrj.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3m4t.jpg', 'Star Wars Knights of the Old Republic II: The Sith Lords is a sequel to the blockbuster RPG Star Wars Knights of the Old Republic. Players continue to enjoy the title''s emotionally compelling and story-driven theme, additions to features such as new characters, classes, locations and force powers as well as a deeper look into the founding lore.', 'https://www.igdb.com/games/star-wars-knights-of-the-old-republic-ii-the-sith-lords', '["Xbox", "Linux", "Android", "PC (Microsoft Windows)", "iOS", "Mac", "Nintendo Switch"]', NULL, 8.6, 0, 1.04, '2026-11-22 03:06:26', '2026-11-22 03:06:26')
