VALUES (NULL, NULL, 167734, 'The Necromancer''s Tale', 'The Necromancer''s Tale', 'game', 2025, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coa54a.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3v8g.jpg', 'A story-rich gothic RPG. Master the rituals of an ancient spellbook. Raise an undead army to march against your enemies. Commune with the realm of the dead & struggle with your descent into madness. Progress through secrecy, diplomacy, blackmail, coercion & seduction until ready to reveal yourself.', 'https://www.igdb.com/games/the-necromancers-tale', '["Xbox Series X|S", "Nintendo Switch 2", "PC (Microsoft Windows)", "PlayStation 5", "Mac"]', NULL, 7.0, 0, 1.04, '2026-11-22 03:06:26', '2026-11-22 03:06:26')
