INSERT INTO "recommendations" ("tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at")
VALUES (NULL, NULL, 2150, 'Split/Second', 'Split/Second', 'game', 2010, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2bw4.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar10ar.jpg', 'Split/Second is an intense action racing game set within a reality television show. Competitors will vie to be the first to the finish line in a made-for-TV city set rigged to blow with the ultimate goal of becoming the season champion. Players in Split/Second don’t just collide with other vehicles to knock them from the track, but can also trigger devastating events that drastically alter the dynamics of the race. Players must use pinpoint timing to obliterate huge structures and towering TV set pieces to tactically alter the track or create entirely new routes.', 'https://www.igdb.com/games/split-second', '["PlayStation 3", "PC (Microsoft Windows)", "iOS", "PlayStation Portable", "Xbox 360"]', NULL, 8.2, 0, 1.01, '2026-11-22 03:06:26', '2026-11-22 03:06:26')
