VALUES (NULL, NULL, 96, 'Need for Speed: Underground', 'Need for Speed: Underground', 'game', 2003, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co209g.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc6x0b.jpg', 'Need for Speed: Underground is a 2003 racing video game and the seventh installment in the Need for Speed series. It rebooted the franchise, ignoring previous Need for Speed games that featured sports cars and exotics. Underground is the first game in the series to offer a career mode that features a comprehensive storyline, as well as a garage mode that allows players to fully customize their cars with a large variety of brand-name performance and visual upgrades.', 'https://www.igdb.com/games/need-for-speed-underground', '["Xbox", "Nintendo GameCube", "PC (Microsoft Windows)", "PlayStation 2"]', NULL, 8.0, 0, 1.01, '2026-11-22 03:06:26', '2026-11-22 03:06:26')
