VALUES (NULL, NULL, 7140, 'Screamer', 'Screamer', 'game', 1995, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6iu7.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1z2k.jpg', 'Screamer is a traditional arcade racing game. The player can drive many different cars such as a Corvette, a Porsche 911, and others. The game has varied tracks, all of which are available in backwards mode. Players can take on the Bullet car for the ultimate championship race.', 'https://www.igdb.com/games/screamer', '["PC (Microsoft Windows)", "Mac", "DOS"]', NULL, 7.6, 0, 1.01, '2026-11-22 03:06:26', '2026-11-22 03:06:26')
