VALUES (NULL, NULL, 3193, 'Need for Speed: Most Wanted', 'Need for Speed: Most Wanted', 'game', 2012, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co20a5.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar6p3g.jpg', 'Need for Speed: Most Wanted takes on the gameplay style of the first Most Wanted title in the Need for Speed franchise. Most Wanted allows players to select one car and compete against other racers in three types of events: Sprint races, which involves traveling from one point of the city to another, Circuit races, each having two or three laps total and Speed runs, which involve traversing through a course in the highest average speed possible. There is also the Ambush races, which start with the player surrounded by cops and tasked to evade their pursuit as quickly as possible.', 'https://www.igdb.com/games/need-for-speed-most-wanted-53b9fef3-adb4-41a0-8ca0-ffcbb0060467', '["PlayStation 3", "PC (Microsoft Windows)", "Xbox 360"]', NULL, 7.9, 0, 1.01, '2026-11-22 03:06:26', '2026-11-22 03:06:26')
