VALUES (NULL, NULL, 23306, 'Asphalt 8: Airborne', 'Asphalt 8: Airborne', 'game', 2013, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1v06.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3lex.jpg', 'With more than 120 million downloads, the best mobile arcade racing game series reaches a new turning point! Perform dynamic, high-speed aerial stunts with more than 90 licensed dream cars in an intense driving experience powered by a brand-new physics engine.', 'https://www.igdb.com/games/asphalt-8-airborne', '["BlackBerry OS", "Windows Phone", "Android", "PC (Microsoft Windows)", "iOS", "Mac"]', NULL, 7.2, 0, 0.0, '2026-11-22 03:06:26', '2026-11-22 03:06:26')
