VALUES (NULL, NULL, 7858, 'Sonic Adventure 2', 'Sonic Adventure 2', 'game', 2001, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cobqpd.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar48hp.jpg', 'Sonic Adventure 2 is the sequel to Sonic Adventure. It was the final Sonic game for the Dreamcast after Sega discontinued the console. Two new playable characters were introduced, Shadow and Rouge, who would go on to become two of the most recurring characters in the Sonic series. The story features good vs evil: Sonic, Tails and Knuckles attempt to save the world, while Shadow, Doctor Eggman and Rouge attempt to conquer it. The levels are divided into three gameplay styles: fast-paced platforming for Sonic and Shadow, multi-directional shooting for Tails and Eggman, and action-exploration for Knuckles and Rouge.', 'https://www.igdb.com/games/sonic-adventure-2', '["Dreamcast"]', NULL, 7.7, 0, 2.05, '2026-11-22 03:06:26', '2026-11-22 03:06:26')
