VALUES (NULL, NULL, 7860, 'Sonic Adventure', 'Sonic Adventure', 'game', 1998, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5jac.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4zl3.jpg', 'Sonic Adventure is a 3D platformer video game in the Sonic the Hedgehog series. The player can control six characters from the Sonic universe, each with their own gameplay and point of view of the story. The game is divided up into two types of levels: Action Stages and Adventure Fields. The division of Action Stages and Adventure Fields are a serious departure from all previous Sonic games. Adventure Fields are non-linear game stages that contain very few items, generally designed for puzzle solving, exploration and plot advancement. Action Stages are more speed based and have Rings scattered in them. Sonic Adventure was the top-selling Dreamcast game and received a sequel in 2001, marking the 10th anniversary of the Sonic the Hedgehog series.', 'https://www.igdb.com/games/sonic-adventure', '["Dreamcast"]', NULL, 6.1, 0, 1.02, '2026-11-22 03:06:26', '2026-11-22 03:06:26')
