VALUES (NULL, NULL, 258663, 'Bobo Bay', 'Bobo Bay', 'game', 2026, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cobtqd.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar2f8h.jpg', 'Bobo Bay is a pet simulation game where you collect, mash(breed), accessorize, and train little creatures to compete in races and other competitions. You are able to feed your Bobo an old shoe which is kinda funny.', 'https://www.igdb.com/games/bobo-bay', '["PC (Microsoft Windows)"]', NULL, NULL, 0, 1.01, '2026-11-22 03:06:26', '2026-11-22 03:06:26')
