VALUES (NULL, NULL, 496, 'Dead Rising 2', 'Dead Rising 2', 'game', 2010, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2gzw.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/okovenpmw5r91neu6vrc.jpg', 'As Chuck Greene, you have 72 hours to save your infected daughter, clear your name and survive the hordes of hungry zombies before the military comes in and nukes the city. To ensure your survival, you can combine everyday objects to create numerous deadly combo weapons and slaughter the ravenous zombies. Dead Rising 2, it’s where Creativity Kills.', 'https://www.igdb.com/games/dead-rising-2', '["PlayStation 3", "PlayStation 4", "Linux", "PC (Microsoft Windows)", "Xbox 360", "Xbox One"]', NULL, 7.7, 0, 1.01, '2026-11-22 03:06:26', '2026-11-22 03:06:26')
