VALUES (NULL, NULL, 5924, 'Dead Rising 2: Off the Record', 'Dead Rising 2: Off the Record', 'game', 2011, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1t1w.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arn3l.jpg', 'The new "Off the Record" storyline means an all new Dead Rising 2 experience. Frank will face off against more twisted enemies, build more outrageous combo weapons, follow his own unique mission structure and explore brand new areas of Fortune City to get his biggest scoop yet. Join Frank as he indulges in the insanity of "Uranus Zone," Fortune City’s very own theme park. Full of deadly rides and crazy attractions, the sci-fi themed Uranus Zone is a true zombie-killing paradise.', 'https://www.igdb.com/games/dead-rising-2-off-the-record', '["PlayStation 3", "PlayStation 4", "PC (Microsoft Windows)", "Xbox 360", "Xbox One"]', NULL, 6.9, 0, 1.01, '2026-11-22 03:06:26', '2026-11-22 03:06:26')
