VALUES (NULL, NULL, 27304, 'Ys VIII: Lacrimosa of Dana', 'Ys VIII: Lacrimosa of Dana', 'game', 2016, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co234k.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4eq3.jpg', 'Ys returns with a brand new adventure for the first time in 8 years! Adol awakens shipwrecked and stranded on a cursed island. There, he and the other shipwrecked passengers he rescues form a village to challenge fearsome beasts and mysterious ruins on the isolated island.', 'https://www.igdb.com/games/ys-viii-lacrimosa-of-dana', '["Google Stadia", "PlayStation 4", "PC (Microsoft Windows)", "PlayStation 5", "PlayStation Vita", "Nintendo Switch"]', NULL, 8.7, 0, 1.02, '2026-11-22 03:06:26', '2026-11-22 03:06:26')
