VALUES (NULL, NULL, 1818, 'Dragon Warrior VII', 'Dragon Warrior VII', 'game', 2000, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7wq9.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc9v8y.jpg', 'Dragon Quest VII is the seventh installment of the popular Dragon Quest series of role playing games and the first in the series to not be a part of a larger trilogy. It was the first main series Dragon Quest title to be released outside of Japan since the release of Dragon Quest IV: Chapters of the Chosen in North America in 1992, and the last DQ title to be released in North America with the Dragon Warrior name.', 'https://www.igdb.com/games/dragon-warrior-vii', '["PlayStation"]', NULL, 8.0, 0, 1.01, '2026-11-22 03:06:26', '2026-11-22 03:06:26')
