VALUES (NULL, NULL, 7236, 'Viva Piñata', 'Viva Piñata', 'game', 2006, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2h1y.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/gny5nxvflmfs0pgxuqql.jpg', 'Attract and tame your favourite Piñatas. There are more than 60 species that roam wild on Piñata Island. Personalise everything from the grass at your feet to the hat on your Piñata''s head. Welcome to Piñata Island, enjoy your stay!', 'https://www.igdb.com/games/viva-pinata', '["PC (Microsoft Windows)", "Xbox 360"]', NULL, 7.5, 0, 1.02, '2026-11-22 03:06:26', '2026-11-22 03:06:26')
