VALUES (NULL, NULL, 172427, 'Kirby and the Forgotten Land', 'Kirby and the Forgotten Land', 'game', 2022, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3vlw.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1cbl.jpg', 'Join Kirby in an unforgettable journey through a mysterious world in a delightful 3D platforming adventure. Take control of the powerful pink puffball, Kirby, and move around freely in 3D stages as you discover a mysterious world with abandoned structures from a past civilization - like a shopping mall?! Copy enemies’ abilities like Sword and Ice and use them to attack and explore your surroundings! What journey awaits Kirby? Take a deep breath and get ready for an unforgettable adventure!', 'https://www.igdb.com/games/kirby-and-the-forgotten-land', '["Nintendo Switch"]', NULL, 8.5, 0, 1.03, '2026-11-22 03:06:26', '2026-11-22 03:06:26')
