VALUES (NULL, NULL, 6770, 'Fantasy Life', 'Fantasy Life', 'game', 2012, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cob8fp.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1kqi.jpg', 'Embark on the adventure of your dream life as you craft, cast, fish, mine, battle and explore like never before. With the innovative Life system, your choices don’t just upgrade characters—they help shape your journey. Explore a huge fantasy landscape beside surly dark paladins, slick pirate captains, regal princesses, and others who share your taste for the unknown.', 'https://www.igdb.com/games/fantasy-life', '["Nintendo 3DS"]', NULL, 7.2, 0, 1.02, '2026-11-22 03:06:26', '2026-11-22 03:06:26')
