VALUES (NULL, NULL, 154973, 'Rise of Piracy', 'Rise of Piracy', 'game', 2026, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4tbv.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1fyg.jpg', 'The perfect blend of Action, Adventure and RTS. Begin your journey as the lowly captain of a small vessel. End as the commander of a threatening fleet. Rise to glory how you see fit. Trade, fight, recruit, grow, pillage, ally, destroy & conquer.', 'https://www.igdb.com/games/rise-of-piracy', '["PC (Microsoft Windows)"]', NULL, NULL, 0, 7.04, '2026-11-22 03:06:26', '2026-11-22 03:06:26')
