VALUES (NULL, NULL, 118323, 'Ultimate Admiral: Age of Sail', 'Ultimate Admiral: Age of Sail', 'game', 2020, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1xe4.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ars1w.jpg', 'Ultimate Admiral: Age of Sail is a tactical war-game from the creators of the Ultimate General series set amidst the epic naval campaigns in period of the American Revolutionary and Napoleonic Wars.', 'https://www.igdb.com/games/ultimate-admiral-age-of-sail', '["PC (Microsoft Windows)"]', NULL, 6.0, 0, 10.02, '2026-11-22 03:06:26', '2026-11-22 03:06:26')
