VALUES (NULL, NULL, 5982, 'Pirates of the Caribbean', 'Pirates of the Caribbean', 'game', 2003, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co45j9.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/fgbye8mzu9vhrvue3ova.jpg', 'Pirates of the Caribbean is a role-playing game in which the player takes the role of a pirate who has to grow in skill by fighting, trading and solving quests. The player can buy and upgrade a ship, sign-up a crew, and try to rule the seas of the Caribbean.', 'https://www.igdb.com/games/pirates-of-the-caribbean', '["Xbox", "PC (Microsoft Windows)"]', NULL, 6.5, 0, 9.01, '2026-11-22 03:06:26', '2026-11-22 03:06:26')
