VALUES (NULL, NULL, 9468, 'Steel Armor: Blaze of War', 'Steel Armor: Blaze of War', 'game', 2011, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3h2e.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ariak.jpg', 'Keep your head cool for this brand new and sizzling hot game from the makers of renowned hardcore-strategy masterpieces like “Steel Fury” and “Achtung Panzer!” With highly versatile strategies and tactics it´s only fair to call their impressive new game “Steel Armor – Blaze of War” one of the most interesting and tactically advanced tank simulations of all time! Plan, command and fight in this exciting and extremely detailed blend of turn-based strategy, real time tactics and full-scaled tank simulation.', 'https://www.igdb.com/games/steel-armor-blaze-of-war', '["PC (Microsoft Windows)"]', NULL, 6.0, 0, 9.01, '2026-11-22 03:06:26', '2026-11-22 03:06:26')
