VALUES (NULL, NULL, 18173, 'Graviteam Tactics: Mius Front', 'Graviteam Tactics: Mius Front', 'game', 2016, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co41fv.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arrgp.jpg', 'Graviteam Tactics: Mius-Front - tactical battalion level combat simulation. Action takes place in the summer of 1943 at Mius river and Saur-Mogila tumulus area of over 140 sq. km. Four large-scale operations for the Red Army and Wehrmacht.', 'https://www.igdb.com/games/graviteam-tactics-mius-front', '["PC (Microsoft Windows)"]', NULL, 8.0, 0, 8.01, '2026-11-22 03:06:26', '2026-11-22 03:06:26')
