VALUES (NULL, NULL, 7443, 'Lichdom: Battlemage', 'Lichdom: Battlemage', 'game', 2014, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2h1x.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arzzb.jpg', 'Lichdom: Battlemage is a first-person caster that gives the Mage the spotlight in a way never before seen in games. With limitless magical power at your disposal and brutal enemies around every corner, victory hinges on a combination of skill and strategy. You must carefully craft a vast array of spells and learn to cast them in the heat of combat.', 'https://www.igdb.com/games/lichdom-battlemage', '["PlayStation 4", "PC (Microsoft Windows)", "Xbox One"]', NULL, 5.8, 0, 9.02, '2026-11-22 03:06:26', '2026-11-22 03:06:26')
