VALUES (NULL, NULL, 18869, 'Mages of Mystralia', 'Mages of Mystralia', 'game', 2017, 'https://images.igdb.com/igdb/image/upload/t_cover_big/dkqoabfj9ka5p0vbeqie.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar6vq.jpg', 'Accompany Zia as she strikes off to train and learn to control her magical abilities that had her exiled. Journey across the lands to meet other exiled mages and uncover runes with magical properties that can be combined into millions of different possibilities, letting you come up with completely new and incredible spells!', 'https://www.igdb.com/games/mages-of-mystralia', '["PlayStation 4", "PC (Microsoft Windows)", "Xbox One", "Nintendo Switch"]', NULL, 8.0, 0, 10.02, '2026-11-22 03:06:26', '2026-11-22 03:06:26')
