VALUES (NULL, NULL, 235597, 'Codex Lost', 'Codex Lost', 'game', 2024, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7q5v.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar24nw.jpg', 'The new open world, spellcasting action-RPG. The grimoires have been stolen, civilisation is in ruins. Rise, Curator! Craft ancient elemental magics and challenge the great lords who threaten to fracture reality itself.', 'https://www.igdb.com/games/codex-lost', '["PC (Microsoft Windows)", "PlayStation 5"]', NULL, NULL, 0, 10.02, '2026-11-22 03:06:26', '2026-11-22 03:06:26')
