VALUES (NULL, NULL, 7331, 'Uncharted 4: A Thief''s End', 'Uncharted 4: A Thief''s End', 'game', 2016, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1r7h.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4pdd.jpg', 'Several years after his last adventure, retired fortune hunter, Nathan Drake, is forced back into the world of thieves. With the stakes much more personal, Drake embarks on a globe-trotting journey in pursuit of a historical conspiracy behind a fabled pirate treasure. His greatest adventure will test his physical limits, his resolve, and ultimately what he''s willing to sacrifice to save the ones he loves.', 'https://www.igdb.com/games/uncharted-4-a-thief-s-end', '["PlayStation 4"]', NULL, 9.2, 0, 8.02, '2026-11-22 03:06:26', '2026-11-22 03:06:26')
