VALUES (NULL, NULL, 140839, 'Mass Effect Legendary Edition', 'Mass Effect Legendary Edition', 'game', 2021, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2k5h.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4mdj.jpg', 'One person is all that stands between humanity and the greatest threat it’s ever faced. Relive the legend of Commander Shepard in the highly acclaimed Mass Effect trilogy with the Mass Effect Legendary Edition. Includes single-player base content and over 40 DLCs from Mass Effect, Mass Effect 2, and Mass Effect 3 games, including promo weapons, armors and packs. Experience an amazingly rich and detailed universe where your decisions have profound consequences on the action and the outcome.', 'https://www.igdb.com/games/mass-effect-legendary-edition', '["Xbox Series X|S", "PlayStation 4", "PC (Microsoft Windows)", "PlayStation 5", "Xbox One"]', NULL, 8.9, 0, 10.01, '2026-11-22 03:06:26', '2026-11-22 03:06:26')
