VALUES (NULL, NULL, 19531, 'Prey', 'Prey', 'game', 2017, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9aoh.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/xulygplf9zfzytu5eyfu.jpg', 'In Prey, you awaken aboard Talos I, a space station orbiting the moon in the year 2032. You are the key subject of an experiment meant to alter humanity forever – but things have gone terribly wrong. The space station has been overrun by hostile aliens and you are now being hunted. As you dig into the dark secrets of Talos I and your own past, you must survive using the tools found on the station, your wits, weapons, and mind-bending abilities.', 'https://www.igdb.com/games/prey--1', '["PlayStation 4", "PC (Microsoft Windows)", "Xbox One"]', NULL, 7.8, 0, 9.8975, '2026-11-19 20:56:22', '2026-11-22 03:06:26')
