VALUES (NULL, NULL, 14593, 'Hollow Knight', 'Hollow Knight', 'game', 2017, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cobfzp.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar584b.jpg', 'A 2D metroidvania with an emphasis on close combat and exploration in which the player enters the once-prosperous now-bleak insect kingdom of Hallownest, travels through its various districts, meets friendly inhabitants, fights hostile ones and uncovers the kingdom''s history while improving their combat abilities and movement arsenal by fighting bosses and accessing out-of-the-way areas.', 'https://www.igdb.com/games/hollow-knight', '["Xbox Series X|S", "PlayStation 4", "Linux", "Nintendo Switch 2", "PC (Microsoft Windows)", "PlayStation 5", "Mac", "Wii U", "Xbox One", "Nintendo Switch"]', NULL, 9.2, 0, 5.52, '2026-11-19 20:56:22', '2026-11-22 03:06:26')
