VALUES (NULL, NULL, 135998, 'Warhammer 40,000: Darktide', 'Warhammer 40,000: Darktide', 'game', 2022, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5j6u.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/aropn.jpg', 'From the developers of the best-selling and award-winning franchise Vermintide, Warhammer 40,000: Darktide is a visceral 4-player co-op action game set in the hive city of Tertium. Fight together with your friends against hordes of enemies in this new Warhammer 40,000 experience.', 'https://www.igdb.com/games/warhammer-40000-darktide', '["Xbox Series X|S", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, 7.5, 0, 8.31800000000000139e+00, '2026-11-19 20:56:22', '2026-11-22 03:06:26')
