VALUES (NULL, NULL, 17583, 'SpellForce 3', 'SpellForce 3', 'game', 2017, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co29i5.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/fjm9uxk8egp2ydx9eky9.jpg', 'SpellForce 3 is the perfect blend between RTS and RPG! The game goes back to the roots of the SpellForce saga. The story takes place before the acclaimed SpellForce: The Order of Dawn and the players becomes a part of a rich high fantasy world named Eo.', 'https://www.igdb.com/games/spellforce-3', '["PC (Microsoft Windows)"]', NULL, 7.1, 0, 5.51500000000000056e+00, '2026-11-19 20:56:22', '2026-11-22 03:06:26')
