VALUES (NULL, NULL, 1164, 'Tomb Raider', 'Tomb Raider', 'game', 2013, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1rbu.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4q0e.jpg', 'Tomb Raider explores the intense and gritty origin story of Lara Croft and her ascent from a young woman to a hardened survivor. Armed only with raw instincts and the ability to push beyond the limits of human endurance, Lara must fight to unravel the dark history of a forgotten island to escape its relentless hold.', 'https://www.igdb.com/games/tomb-raider--2', '["PlayStation 3", "Linux", "Android", "PC (Microsoft Windows)", "iOS", "Mac", "Xbox 360"]', NULL, 8.3, 0, 6.01500000000000056e+00, '2026-11-19 20:56:22', '2026-11-22 03:06:26')
