VALUES (NULL, NULL, 279627, 'No Rest for the Wicked', 'No Rest for the Wicked', 'game', 2024, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7h9r.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3v3z.jpg', 'From Moon Studios, the award-winning developers of Ori and the Blind Forest and Ori and the Will of the Wisps comes No Rest for the Wicked, a visceral, precision Action RPG set to reinvent the genre.', 'https://www.igdb.com/games/no-rest-for-the-wicked--1', '["Xbox Series X|S", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, 8.0, 0, 2.015, '2026-11-19 20:56:22', '2026-11-22 03:06:26')
