VALUES (NULL, NULL, 89538, 'Sprocket', 'Sprocket', 'game', 2021, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5nxi.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar11gw.jpg', 'Carefully balance mobility, firepower and armour in a dedicated tank designer. Then uncarefully put them to the test in a series of combat scenarios progressing through the ages of the tank. Here, your limit is what you can fit inside your hull and turret while still being able to move forwards.', 'https://www.igdb.com/games/sprocket', '["PC (Microsoft Windows)"]', NULL, NULL, 0, 6.09, '2026-11-19 20:56:22', '2026-11-22 03:06:26')
