VALUES (NULL, NULL, 9630, 'Fallout 4', 'Fallout 4', 'game', 2015, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1yc6.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/cyhl4l49l08mkwtus2y4.jpg', 'Bethesda Game Studios welcome you to the world of Fallout 4, their most ambitious game ever, and the next generation of open-world gaming. As the sole survivor of Vault 111, you enter a world destroyed by nuclear war. Every second is a fight for survival, and every choice is yours. Only you can rebuild and determine the fate of the Wasteland. Welcome home.', 'https://www.igdb.com/games/fallout-4', '["Xbox Series X|S", "PlayStation 4", "PC (Microsoft Windows)", "PlayStation 5", "Xbox One"]', NULL, 8.2, 0, 8.03399999999999892e+00, '2026-11-19 20:56:22', '2026-11-22 03:06:26')
