VALUES (NULL, NULL, 4797, 'Dead Rising', 'Dead Rising', 'game', 2006, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co20xf.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar6qh8.jpg', 'Frank West, a freelance photojournalist on the hunt for the scoop of a lifetime, pursues a juicy lead to a small suburban town only to find that it is being overrun by zombies! He escapes to the local shopping mall thinking it will be a bastion of safety, but it turns out to be anything but. It''s a true struggle to survive the endless stream of enemies, but with full reign over an entire shopping center, Frank can utilize anything to fight off the flesh-hungry mob and search for the truth behind the horrendous epidemic.', 'https://www.igdb.com/games/dead-rising', '["PlayStation 4", "PC (Microsoft Windows)", "Xbox 360", "Xbox One"]', NULL, 7.9, 0, 3.04666666666666685e+00, '2026-11-19 20:56:22', '2026-11-22 03:06:26')
