VALUES (NULL, NULL, 1184, 'World of Tanks', 'World of Tanks', 'game', 2011, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cod7bd.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3qaj.jpg', 'Jump into the free-to-play team-based shooter with an ever-expanding roster of historical vehicles, stunning graphics, spectacular locales, and orchestral scores. Battle it out in the company of other players in thrilling military conflicts. A unique mix of strategy and action awaits!', 'https://www.igdb.com/games/world-of-tanks', '["PC (Microsoft Windows)"]', NULL, 7.5, 0, 9.745, '2026-11-20 22:18:41', '2026-11-22 03:06:26')
