VALUES (NULL, NULL, 2165, 'War Thunder', 'War Thunder', 'game', 2013, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1p78.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arotq.jpg', 'War Thunder is a free-to-play vehicular combat MMO featuring aircraft, ground vehicles, and naval craft spanning from the early 20th century to the modern era. Players progress through technology trees across multiple nations, unlocking increasingly advanced military vehicles. The game offers three realism tiers for each vehicle type: arcade, realistic, and simulator modes. Originally developed as a flight simulator under the name "World of Planes," the game expanded to include tanks in 2014 and naval forces later, becoming a combined-arms experience. A mobile version was released in 2023.', 'https://www.igdb.com/games/war-thunder', '["Xbox Series X|S", "PlayStation 4", "Linux", "PC (Microsoft Windows)", "PlayStation 5", "Mac", "Xbox One"]', NULL, 6.9, 0, 10.03, '2026-11-20 22:18:41', '2026-11-22 03:06:26')
