VALUES (NULL, NULL, 2369, 'Dark Messiah of Might and Magic', 'Dark Messiah of Might and Magic', 'game', 2006, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co23t5.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar5ulu.jpg', 'Discover a new breed of Action-RPG game powered by an enhanced version of the Source Engine by Valve. Set in the Might & Magic universe, players will experience ferocious combat in a dark and immersive fantasy environment. Swords, Stealth, Sorcery. Choose your way to kill.', 'https://www.igdb.com/games/dark-messiah-of-might-and-magic', '["PC (Microsoft Windows)"]', NULL, 7.7, 0, 6.04, '2026-11-21 21:29:28', '2026-11-22 03:06:26')
