VALUES (NULL, NULL, 36929, 'Pathfinder: Kingmaker', 'Pathfinder: Kingmaker', 'game', 2018, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co29gf.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arp7n.jpg', 'Pathfinder: Kingmaker is the first isometric party-based computer RPG set in the Pathfinder fantasy universe. Enjoy a classic RPG experience inspired by games like Baldur''s Gate, Fallout 1 and 2 and Arcanum. Explore and conquer the Stolen Lands and make them your kingdom!', 'https://www.igdb.com/games/pathfinder-kingmaker', '["PlayStation 4", "Linux", "PC (Microsoft Windows)", "Mac", "Xbox One", "Nintendo Switch"]', NULL, 7.5, 0, 8.285, '2026-11-21 21:29:28', '2026-11-22 03:06:26')
